def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    if len(pts)<2:
        return out
    dr=pts[-1][0]-pts[-2][0]
    dc=pts[-1][1]-pts[-2][1]
    r,c=pts[-1]
    while 0<=r+dr<len(out) and 0<=c+dc<len(out[0]):
        r+=dr; c+=dc
        out[r][c]=2
    return out

